import React from 'react';
import classNames from 'classnames';
import Button from '../../atoms/button';
import Text from '../../atoms/text';
import BrandedHeading from '../../atoms/brandedHeading';
import { SvgPageNotFound } from '../../atoms/svgs';
import './index.less';
import { ColorNameEnum, SizeEnum, WeightEnum } from '../../types';

interface ErrorPageProps {
  className?: string;
  title: string;
  subtitle: string;
  buttonText: string;
  onClick: () => any;
}

export default function ErrorPage({
  onClick,
  buttonText,
  title,
  subtitle,
  className,
}: ErrorPageProps) {
  return (
    <div className={classNames('error-page', className)}>
      <BrandedHeading text={title} size="small" margin="none" />

      <Text
        className="margin-top-10 margin-bottom-45"
        size={SizeEnum['14px']}
        colorName={ColorNameEnum.ultraDark}
        weight={WeightEnum.medium}
        text={subtitle}
      />

      <SvgPageNotFound />

      <div className="text-center">
        <Button
          text={buttonText}
          buttonType="small"
          bgColor="themedOutline"
          width="small"
          onClick={onClick}
        />
      </div>
    </div>
  );
}
